    const cap=story.levelCap(s.adv),byRegion=Object.fromEntries(story.REGIONS.filter(r=>r.key&&r.ace).map(r=>[r.key,story.regionCap(s.adv,r.key)]));
    const ch=CAP_DATA.chapters[s.adv.chapter],key=s.link?(s.link.side==='from'?s.link.from:s.link.to):(ch?.reg||'kanto');
